declare(strict_types=1);

/* Builds a self-contained Chapter IV manuscript with low-fidelity figures. */
$outDir = __DIR__ . DIRECTORY_SEPARATOR . 'capstone_build';
if (!is_dir($outDir)) mkdir($outDir, 0777, true);

function esc(string $s): string { return htmlspecialchars($s, ENT_XML1 | ENT_QUOTES, 'UTF-8'); }
function canvas(string $name, int $w = 1400, int $h = 800) {
    global $outDir;
    $im = imagecreatetruecolor($w, $h);
    imagefill($im, 0, 0, imagecolorallocate($im, 255, 255, 255));
    return [$im, $outDir . DIRECTORY_SEPARATOR . $name, $w, $h];
}
function line($im, int $x1, int $y1, int $x2, int $y2, int $width = 3): void {
    $c = imagecolorallocate($im, 45, 45, 45); imagesetthickness($im, $width); imageline($im, $x1, $y1, $x2, $y2, $c);
}
function arrow($im, int $x1, int $y1, int $x2, int $y2): void {
    line($im, $x1, $y1, $x2, $y2); $a = atan2($y2 - $y1, $x2 - $x1);
    line($im, $x2, $y2, (int)($x2 - 16*cos($a-.45)), (int)($y2 - 16*sin($a-.45)));
    line($im, $x2, $y2, (int)($x2 - 16*cos($a+.45)), (int)($y2 - 16*sin($a+.45)));
}
function box($im, int $x, int $y, int $w, int $h, string $text, int $size = 22): void {
    $black = imagecolorallocate($im, 35, 35, 35); $fill = imagecolorallocate($im, 245, 245, 245);
    imagefilledrectangle($im, $x, $y, $x+$w, $y+$h, $fill); imagesetthickness($im, 3); imagerectangle($im, $x, $y, $x+$w, $y+$h, $black);
    $font = 'C:\\Windows\\Fonts\\arial.ttf'; $lines = explode("\n", $text); $lh = $size + 8; $start = $y + (int)(($h - count($lines)*$lh)/2) + $size;
    foreach ($lines as $i => $t) { $bb = imagettfbbox($size, 0, $font, $t); $tw = $bb[2]-$bb[0]; imagettftext($im,$size,0,$x+(int)(($w-$tw)/2),$start+$i*$lh,$black,$font,$t); }
}
function label($im, int $x, int $y, string $text, int $size = 24): void {
    $font = 'C:\\Windows\\Fonts\\arial.ttf'; $black = imagecolorallocate($im, 25, 25, 25); imagettftext($im,$size,0,$x,$y,$black,$font,$text);
}
function save($im, string $path): string { imagepng($im, $path); imagedestroy($im); return $path; }
function flowFigure(string $name, array $steps): string {
    [$im,$path,$w,$h] = canvas($name, 1400, 430); label($im, 50, 55, 'Current Business Process: Crime Incident Reporting and Recording', 28);
    $count = count($steps); $bw = 210; $gap = (int)((1300-$count*$bw)/($count-1)); foreach ($steps as $i=>$s) { $x=50+$i*($bw+$gap); box($im,$x,150,$bw,120,$s,18); if($i<$count-1) arrow($im,$x+$bw,210,$x+$bw+$gap-10,210); } return save($im,$path);
}
function architectureFigure(): string {
    [$im,$path] = canvas('architecture.png', 1400, 760); label($im,50,55,'Three-Tier System Architecture',28);
    box($im,100,115,1200,150,"PRESENTATION LAYER\nWeb browser interface: Login, Dashboard, Map, Crimes, Evidence, Reports",24);
    arrow($im,700,265,700,330); box($im,100,335,1200,170,"APPLICATION / BUSINESS LOGIC LAYER\nLaravel Controllers, Authentication, Role Authorization, Validation, Case Numbering, Analytics, Audit Logging",23);
    arrow($im,700,505,700,570); box($im,100,575,1200,130,"DATA LAYER\nMySQL Database and File Storage: Users, Crimes, Types, Barangays, Evidence, Audit Logs",24); return save($im,$path);
}
function ipoFigure(): string {
    [$im,$path] = canvas('conceptual_framework.png', 1400, 600); label($im,50,55,'Conceptual Framework: Input-Process-Output',28);
    box($im,55,160,360,280,"INPUT\nUser accounts and roles\nCrime reports and locations\nCrime/offense types\nBarangay boundaries\nEvidence files",22); arrow($im,420,300,505,300);
    box($im,510,160,380,280,"PROCESS\nAuthenticate users\nValidate and record crimes\nMap and locate incidents\nAttach evidence\nAnalyze and generate reports",22); arrow($im,895,300,980,300);
    box($im,985,160,360,280,"OUTPUT\nCrime case records\nInteractive crime map\nHotspot and trend analytics\nEvidence repository\nFiltered reports",22); return save($im,$path);
}
