    [$im,$path] = canvas('use_case.png', 1500, 900); label($im,50,55,'Use Case Diagram: Crime Mapping and Management System',28);
    $black=imagecolorallocate($im,35,35,35); imagesetthickness($im,3); imagerectangle($im,340,100,1320,840,$black); label($im,680,135,'Crime Mapping and Management System',22);
    foreach ([[60,210,'Police Officer'],[60,470,'Investigator'],[60,710,'Administrator'],[1360,450,'LGU User']] as [$x,$y,$t]) { imageellipse($im,$x+45,$y,30,30,$black); line($im,$x+45,$y+15,$x+45,$y+75); line($im,$x+15,$y+40,$x+75,$y+40); line($im,$x+45,$y+75,$x+20,$y+110); line($im,$x+45,$y+75,$x+70,$y+110); label($im,$x,$y+145,$t,18); }
    $cases=[[470,185,'Record Crime'],[770,185,'View Crime Map'],[1060,185,'Generate Reports'],[470,380,'Upload Evidence'],[770,380,'Update Case Status'],[1060,380,'View Analytics'],[470,590,'Manage Users'],[770,590,'Manage Reference Data'],[1060,590,'Review Audit Logs']];
    foreach($cases as [$x,$y,$t]) { imageellipse($im,$x+110,$y+35,220,70,$black); $bb=imagettfbbox(18,0,'C:\\Windows\\Fonts\\arial.ttf',$t); imagettftext($im,18,0,$x+110-(int)(($bb[2]-$bb[0])/2),$y+41,$black,'C:\\Windows\\Fonts\\arial.ttf',$t); }
    foreach ([[105,250,470,220],[105,250,470,415],[105,510,770,415],[105,510,770,220],[105,750,470,625],[105,750,770,625],[105,750,1060,625],[1405,490,770,220],[1405,490,1060,220],[1405,490,1060,415]] as $l) line($im,$l[0],$l[1],$l[2],$l[3],2); return save($im,$path);
}
function activityFigure(string $name, string $title, array $steps): string {
    [$im,$path] = canvas($name, 1400, 210 + count($steps)*110); label($im,50,55,$title,28); $x=490; imageellipse($im, $x+170,95,28,28,imagecolorallocate($im,35,35,35)); $y=125;
    foreach($steps as $i=>$s) { arrow($im,$x+170,$y,$x+170,$y+32); box($im,$x,$y+35,340,62,$s,19); $y += 97; } arrow($im,$x+170,$y,$x+170,$y+30); imagefilledellipse($im,$x+170,$y+48,30,30,imagecolorallocate($im,35,35,35)); return save($im,$path);
}
function wireframe(string $name, string $title, array $body): string {
    [$im,$path] = canvas($name, 1400, 850); $black=imagecolorallocate($im,35,35,35); imagesetthickness($im,4); imagerectangle($im,100,80,1300,780,$black); label($im,120,55,'LOW-FIDELITY WIREFRAME - '.$title,25);
    imagefilledrectangle($im,104,84,1296,145,imagecolorallocate($im,235,235,235)); line($im,104,145,1296,145); label($im,130,123,'CRIME MAPPING AND MANAGEMENT SYSTEM',18); label($im,1115,123,'[User] [Logout]',17);
    if ($title !== 'Login') { imagefilledrectangle($im,104,149,330,776,imagecolorallocate($im,245,245,245)); line($im,330,149,330,776); foreach(['Dashboard','Crime Records','Evidence','Map','Hotspots','Analytics','Reports','Users'] as $i=>$item) label($im,130,195+$i*60,'[ ] '.$item,17); }
    $left=$title==='Login'?340:365; $top=185; foreach($body as $entry) { [$x,$y,$w,$h,$txt]=$entry; box($im,$left+$x,$top+$y,$w,$h,$txt,17); } return save($im,$path);
}

