function para(string $text='', string $style='Normal', bool $bold=false): string { $r='<w:r>'.($bold?'<w:rPr><w:b/></w:rPr>':'').'<w:t xml:space="preserve">'.esc($text).'</w:t></w:r>'; return '<w:p><w:pPr><w:pStyle w:val="'.$style.'"/></w:pPr>'.$r.'</w:p>'; }
function bullets(array $items): string { $o=''; foreach($items as $item) $o.='<w:p><w:pPr><w:ind w:left="720" w:hanging="360"/></w:pPr><w:r><w:t>• </w:t></w:r><w:r><w:t>'.esc($item).'</w:t></w:r></w:p>'; return $o; }
function table(array $headers, array $rows): string { $s='<w:tbl><w:tblPr><w:tblBorders><w:top w:val="single" w:sz="8"/><w:left w:val="single" w:sz="8"/><w:bottom w:val="single" w:sz="8"/><w:right w:val="single" w:sz="8"/><w:insideH w:val="single" w:sz="4"/><w:insideV w:val="single" w:sz="4"/></w:tblBorders></w:tblPr>'; foreach(array_merge([$headers],$rows) as $ri=>$row){$s.='<w:tr>';foreach($row as $cell){$s.='<w:tc><w:tcPr><w:tcW w:w="'.(int)(9000/count($headers)).'" w:type="dxa"/></w:tcPr>'.para($cell,'Normal',$ri===0).'</w:tc>';}$s.='</w:tr>';} return $s.'</w:tbl>'; }
function imagePara(string $path, int $id, string $title): string { global $rels,$media; $name='image'.$id.'.png'; $media[$name]=$path; $rels[]='<Relationship Id="rId'.$id.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/'.$name.'"/>'; $size=getimagesize($path); $cx=(int)min(6200000, $size[0]*5000); $cy=(int)($size[1]*($cx/$size[0])); return '<w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"><wp:extent cx="'.$cx.'" cy="'.$cy.'"/><wp:docPr id="'.$id.'" name="'.$name.'" descr="'.esc($title).'"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="'.$id.'" name="'.$name.'"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rId'.$id.'" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'.$cx.'" cy="'.$cy.'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>'; }
function pageBreak(): string { return '<w:p><w:r><w:br w:type="page"/></w:r></w:p>'; }

$doc[] = para('CHAPTER IV','Title'); $doc[] = para('METHODOLOGY, RESULTS, AND DISCUSSION','Subtitle'); $doc[] = para('Crime Mapping and Management System for Koronadal City','Subtitle');
$doc[] = para('4.1 Requirements Analysis','Heading1'); $doc[] = para('4.1.1 Current Technical Situation','Heading2');
$doc[] = para('The current handling of crime incidents in Koronadal City relies heavily on manual reporting, paper-based documentation, and separate records maintained by concerned offices. A citizen reports an incident to a police officer, who records the information and forwards it for review and filing. This arrangement makes it difficult to locate past cases quickly, track case progress, consolidate evidence, and identify geographic crime patterns. Information may be duplicated across forms, updates can be delayed, and decision makers do not have a single real-time view of crime incidents. The proposed Crime Mapping and Management System addresses these limitations by centralizing crime records, evidence, case-status monitoring, mapping, analytics, and reporting in one role-based web application.');
$doc[] = imagePara($figures['Figure 1. Current Business Process of Crime Incident Reporting and Recording'],$rid++,'Current business process'); $doc[] = para('Figure 1. Current Business Process of Crime Incident Reporting and Recording','Caption');
$doc[] = para('Figure 1 shows the existing process from the occurrence of an incident up to the filing of a paper report. The citizen provides incident details to the police officer, who manually writes the information before it is reviewed by a supervisor and stored in office files. Since the record is not immediately available in a centralized database, personnel must search physical documents when they need information about a case. The process also does not directly provide a map view, automated statistics, or an audit trail of updates.');
$doc[] = para('4.2 Requirements Documentation','Heading1'); $doc[] = para('The following low-fidelity wireframes serve as the blueprint of the proposed system. They use simple grayscale boxes, lines, and text placeholders to emphasize layout, navigation consistency, record actions, reports, and notifications before high-fidelity interface development.');
foreach(['Figure 2. Low-Fidelity Wireframe: Login Page','Figure 3. Low-Fidelity Wireframe: Dashboard with Navigation Bar','Figure 4. Low-Fidelity Wireframe: Crime Records and Delete Action','Figure 5. Low-Fidelity Wireframe: Add/Edit Crime Record','Figure 6. Low-Fidelity Wireframe: Reports','Figure 7. Low-Fidelity Wireframe: Notifications'] as $caption){$doc[]=imagePara($figures[$caption],$rid++,$caption);$doc[]=para($caption,'Caption');}
$doc[] = para('4.2.1 Functional Requirements','Heading2');
$functional = [['FR-01','The system shall allow authorized users to sign in, sign out, and reset passwords through OTP verification.'],['FR-02','The system shall provide role-based access for administrators, police officers, investigators, and LGU users.'],['FR-03','The system shall allow police officers to create crime records with type, offense type, date, location, barangay, description, and status.'],['FR-04','The system shall generate a unique case number for every new crime record.'],['FR-05','The system shall allow authorized personnel to view, search, filter, edit, and soft-delete crime records.'],['FR-06','The system shall display crime incidents on an interactive map and associate incidents with barangays.'],['FR-07','The system shall allow authorized users to upload, view, and manage evidence files attached to a crime record.'],['FR-08','The system shall allow investigators to record findings and update a case status.'],['FR-09','The system shall display dashboard counts, trends, hotspot data, and crime summaries by type, barangay, and status.'],['FR-10','The system shall generate filtered reports by crime type, barangay, status, and date range, with print/PDF output.'],['FR-11','The system shall allow administrators to manage user accounts, crime types, offense types, and barangay reference data.'],['FR-12','The system shall record audit logs for significant actions performed by users and show success, warning, confirmation, or error notifications.']];
$doc[] = table(['ID','Requirement'],$functional);
$doc[] = para('4.2.2 Non-Functional Requirements','Heading2');
$nonfunctional = [['Performance','Common dashboard, record-search, and report-filter requests should return within three seconds under normal use.'],['Reliability','Validated records, transactions, and audit logs shall reduce erroneous or incomplete data updates.'],['Availability','The web system shall be available to authorized offices during agreed service hours, subject to scheduled maintenance.'],['Security','Passwords shall be hashed; access shall be role-based; inputs shall be validated; sessions and file uploads shall be protected.'],['Usability','Screens shall keep navigation, buttons, labels, filters, and notifications consistent across major workflows.'],['Maintainability','The Laravel MVC structure, migrations, and separated models/controllers shall support controlled maintenance.'],['Scalability','Indexed columns and normalized tables shall support increasing crime records, evidence files, and users.'],['Compatibility','The system shall operate on current desktop browsers with a standard internet/intranet connection.'],['Portability','The application shall be deployable to a PHP/Laravel-compatible server with MySQL.'],['Data Integrity','Primary keys, foreign keys, validation rules, unique case numbers, and controlled reference tables shall preserve accurate data.']];
$doc[] = table(['Quality Attribute','Requirement'],$nonfunctional);
$doc[] = pageBreak(); $doc[] = para('4.3 Design of Software, System, Product, and/or Process','Heading1'); $doc[] = para('4.3.1 Conceptual Framework','Heading2');
$doc[] = para('The conceptual framework follows the Input-Process-Output model. Inputs include user accounts, incident information, crime and offense classifications, barangay data, and evidence files. The process authenticates users, validates and stores records, maps incident locations, manages evidence, monitors cases, and produces analytics and reports. The output is a centralized crime-management environment that provides current case information, spatial crime views, decision-support statistics, and accountable reporting.');
$doc[] = imagePara($figures['Figure 8. Conceptual Framework of the Proposed System'],$rid++,'Conceptual framework'); $doc[] = para('Figure 8. Conceptual Framework of the Proposed System','Caption');
$doc[] = para('4.3.2 System Architecture','Heading2'); $doc[] = para('The proposed system uses a three-tier architecture. In the presentation layer, authorized users access the web interface through their browsers to sign in, manage records, view maps, upload evidence, and generate reports. In the application or business-logic layer, the Laravel application handles authentication, role authorization, validation, case numbering, reporting, analytics, and audit logging. In the data layer, MySQL stores normalized operational data while configured file storage retains evidence documents. This separation improves maintainability, security, and scalability because user-interface, processing, and data responsibilities are managed independently.');
$doc[] = imagePara($figures['Figure 9. Three-Tier System Architecture'],$rid++,'Three tier architecture'); $doc[] = para('Figure 9. Three-Tier System Architecture','Caption');
$doc[] = para('4.3.3 Use Case Diagram','Heading2'); $doc[] = para('The use case diagram identifies the system actors and their major interactions. Police officers record incidents, attach evidence, and consult the map. Investigators review cases and update their status based on findings. Administrators manage users and reference data and review audit logs, while LGU users can view authorized map, analytics, and report information. These use cases represent the core functional requirements of the system.');
$doc[] = imagePara($figures['Figure 10. Use Case Diagram of the Proposed System'],$rid++,'Use case diagram'); $doc[] = para('Figure 10. Use Case Diagram of the Proposed System','Caption');
$doc[] = para('4.3.4 Activity Diagrams','Heading2'); $doc[] = para('The first activity diagram describes the process for recording a crime incident. The activity begins when a police officer signs in, enters validated details, and submits the record. The system assigns a case number, saves the record, creates an audit entry, and confirms the result. The second activity diagram covers case-status updates, where an investigator reviews the relevant case and evidence before selecting an authorized status change that is validated and logged by the system.');
foreach(['Figure 11. Activity Diagram for Recording a Crime Incident','Figure 12. Activity Diagram for Updating Case Status'] as $caption){$doc[]=imagePara($figures[$caption],$rid++,$caption);$doc[]=para($caption,'Caption');}
$doc[] = pageBreak(); $doc[] = para('4.4 Database Normalization','Heading1'); $doc[] = para('Before normalization, the proposed database stores operational information about users, crime records, classifications, barangays, evidence files, and audit activities. Normalization is applied to eliminate repeating groups, reduce data duplication, and maintain dependable relationships among records.');
$doc[] = para('4.4.1 Unnormalized Form (UNF)','Heading2'); $doc[] = para('A single unnormalized crime-report record may contain multiple evidence names and file paths in repeating columns, as well as repeating crime-type, offense-type, barangay, and officer details. This structure is difficult to extend because every new evidence item would require another column.');
$doc[] = table(['Case No.','Crime Type','Evidence 1','Evidence 2','Officer Name','Barangay'],[['CRM-20260731-0001','Theft','Photo A','Statement A','Juan Dela Cruz','General Paulino Santos']]);
$doc[] = para('4.4.2 First Normal Form (1NF)','Heading2'); $doc[] = para('In 1NF, each field contains only one value. Repeating evidence groups are removed by storing each evidence item in a separate row. Although the data is atomic, case, type, barangay, and officer details may still repeat for every evidence row.');
$doc[] = table(['Case No.','Crime Type','Evidence File','Officer Name','Barangay'],[['CRM-20260731-0001','Theft','Photo A','Juan Dela Cruz','General Paulino Santos'],['CRM-20260731-0001','Theft','Statement A','Juan Dela Cruz','General Paulino Santos']]);
$doc[] = para('4.4.3 Second Normal Form (2NF)','Heading2'); $doc[] = para('In 2NF, attributes that depend only on part of a composite relationship are separated. Crime details are kept in the Crimes table, while evidence details are moved to an Evidence table linked by crime_id. Reference data such as crime type and barangay are also separated so their names are not repeated in every crime record.');
$doc[] = table(['Table','Primary Key','Key Attributes'],[['Crimes','crime_id','case_number, crime_type_id, barangay_id, reported_by, status'],['Evidence','evidence_id','crime_id, file_name, file_path, uploaded_by'],['CrimeTypes','crime_type_id','name, description, is_active'],['Barangays','barangay_id','name, boundaries']]);
$doc[] = para('4.4.4 Third Normal Form (3NF)','Heading2'); $doc[] = para('In 3NF, non-key attributes depend only on their table primary key. Offense types are stored independently and referenced by crimes; users are stored separately from the crimes they report or the evidence they upload; and audit data is placed in its own table. The resulting design prevents transitive dependencies and makes names, classifications, and account details easier to update without changing historical crime records.');
$doc[] = table(['Table','Primary Key','Foreign Keys / Main Attributes'],[['users','id','name, email, password, role, is_active'],['crime_types','id','name, description, is_active'],['offense_types','id','crime_type_id, name, description, is_active'],['barangays','id','name, boundary data'],['crimes','id','crime_type_id, offense_type_id, barangay_id, reported_by, case_number, date, location, status'],['evidence','id','crime_id, uploaded_by, file_name, file_path, file_type, description'],['audit_logs','id','user_id, action, auditable_type, auditable_id, old_values, new_values']]);
